WITH scored AS (SELECT *, ROW_NUMBER() OVER w_ordered AS row_seq, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY started_at DESC, id) AS event_seq, ROW_NUMBER() OVER w_part AS row_seq_2 FROM sessions WINDOW w_ordered AS (PARTITION BY customer_id, browser ORDER BY started_at, id), w_part AS (PARTITION BY device, customer_id ORDER BY started_at DESC, id)) SELECT s.id, s.customer_id, s.started_at, s.country, s.row_seq, s.event_seq, s.row_seq_2, (SELECT SUM(t2.monthly_fee) FROM subscriptions t2 WHERE t2.customer_id = s.customer_id) AS sum_subscription_monthly_fee FROM scored s
